import json,re
p='/tmp/llm_rollout_smoke_test/seed_collection_0012_embedded_hardcodes_2160__rollout_v1.json'
d=json.load(open(p))
fill={
'E2','G4','I4','K4','G5','I5','K5','E39','G39','I39','E41','G41','I41','E42','G42','I42','E67','G67','I67','E68','G68','I68','E70','G70','I70','E71','G71','I71','E72','G72','I72','E74','F76','H76','J76','F77','H77','J77','F79','H79','J79','F81','H81','J81'}
cells=set()
for msg in d['messages']:
    if msg['role']=='tool':
        c=msg.get('content','')
        if 'Sheet1' in c:
            for line in c.splitlines():
                m=re.match(r'^([E-K]\d+) ', line)
                if m:
                    coord=m.group(1)
                    rest=line[m.end():].strip()
                    if rest.startswith("'="):
                        continue
                    cells.add(coord)
print('2160 E-K nonformula count', len(cells))
print('missing in fill', sorted(cells-fill))
print('extra in fill', sorted(fill-cells))
print('cells:', sorted(cells))
